<?php
if(!defined('SCHOOLOS_INSIGHTS_LIBRARY')){header('Location: index.php?s=intelligence&area=innovations');exit;}
function si_schema():array{return [
 "CREATE TABLE IF NOT EXISTS ix_alerts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,window_day DATE NOT NULL,evidence_json TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',review_note TEXT NULL,reviewed_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY once_alert(tenant_id,student_id,kind,window_day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS ix_drafts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,payload_json TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reviewed_by BIGINT UNSIGNED NULL,review_note VARCHAR(1000) NULL,result_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS ix_ai_usage(tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,usage_day DATE NOT NULL,used INT NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,user_id,usage_day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS ix_pickup_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,authorization_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',issued_by BIGINT UNSIGNED NOT NULL,verified_by BIGINT UNSIGNED NULL,identity_note VARCHAR(500) NULL,verified_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS ix_wa_flows(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,command VARCHAR(20) NOT NULL,template_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL,review_note VARCHAR(500) NOT NULL,UNIQUE KEY school_flow(tenant_id,command)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS ix_wa_inbound(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,provider_id VARCHAR(190) NOT NULL,command VARCHAR(20) NOT NULL,outcome VARCHAR(30) NOT NULL,user_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY inbound_once(tenant_id,provider_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS ix_sync(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,event_key VARCHAR(80) NOT NULL,payload_hash CHAR(64) NOT NULL,result_json TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY once_sync(tenant_id,user_id,event_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function si_evidence(int $tid,int $sid):array{
 $alerts=[];$records=q('SELECT attendance_date,status FROM attendance WHERE tenant_id=? AND student_id=? AND attendance_date<=CURRENT_DATE() ORDER BY attendance_date DESC LIMIT 40',[$tid,$sid])->fetchAll();if(count($records)>=10){$n=min(20,intdiv(count($records),2));$recent=array_slice($records,0,$n);$prior=array_slice($records,$n,$n);$rate=static fn($rows)=>round(100*count(array_filter($rows,fn($r)=>in_array($r['status'],['present','late'],true)))/count($rows),2);$new=$rate($recent);$old=$rate($prior);if($new<80||$old-$new>=10)$alerts['attendance']=['recent_recorded'=>$n,'prior_recorded'=>$n,'recent_percent'=>$new,'prior_percent'=>$old,'rule'=>'Recent attendance below 80% or decline of at least 10 points; unrecorded days excluded'];}
 $scores=q("SELECT a.id,a.title,a.session_name,a.term_name,sc.score/a.max_score*100 pct FROM ac_scores sc JOIN ac_assessments a ON a.id=sc.assessment_id AND a.tenant_id=sc.tenant_id JOIN ac_term_approvals p ON p.tenant_id=a.tenant_id AND p.class_id=a.class_id AND p.session_name=a.session_name AND p.term_name=a.term_name AND p.status='published' WHERE sc.tenant_id=? AND sc.student_id=? AND sc.status='approved' AND a.max_score>0 ORDER BY a.created_at DESC,a.id DESC LIMIT 4",[$tid,$sid])->fetchAll();if(count($scores)===4){$new=((float)$scores[0]['pct']+(float)$scores[1]['pct'])/2;$old=((float)$scores[2]['pct']+(float)$scores[3]['pct'])/2;if($old-$new>=10)$alerts['performance']=['recent_mean'=>round($new,2),'prior_mean'=>round($old,2),'assessments'=>array_column($scores,'id'),'rule'=>'Two latest published approved components average at least 10 points below prior two; components may differ in subject/difficulty'];}
 $s=q('SELECT class_id FROM students WHERE tenant_id=? AND id=?',[$tid,$sid])->fetch();if($s){$work=q("SELECT l.id,(x.id IS NOT NULL) done,l.due_at FROM lm_lessons l JOIN lm_courses c ON c.id=l.course_id AND c.tenant_id=l.tenant_id LEFT JOIN lm_submissions x ON x.lesson_id=l.id AND x.tenant_id=l.tenant_id AND x.student_id=? WHERE l.tenant_id=? AND c.class_id=? AND c.status='published' AND l.lesson_type='homework' AND l.due_at BETWEEN DATE_SUB(NOW(),INTERVAL 30 DAY) AND NOW() AND (l.available_at IS NULL OR l.available_at<=NOW()) ORDER BY l.due_at DESC LIMIT 100",[$sid,$tid,$s['class_id']])->fetchAll();if(count($work)>=3){$done=array_sum(array_column($work,'done'));$pct=round(100*$done/count($work),2);if($pct<60)$alerts['homework']=['assigned_overdue'=>count($work),'submitted'=>$done,'completion_percent'=>$pct,'lesson_ids'=>array_column($work,'id'),'rule'=>'Below 60% submission across at least three currently assigned homework activities due in last 30 days; enrollment history and exceptions require staff review'];}}
 return $alerts;
}
function si_scan(array $u):int{ix_need($u,'success_reviewer');$count=0;foreach(q('SELECT id FROM students WHERE tenant_id=? ORDER BY id LIMIT 2000',[$u['tenant_id']])->fetchAll() as $s)foreach(si_evidence((int)$u['tenant_id'],(int)$s['id']) as $kind=>$evidence)$count+=q('INSERT IGNORE INTO ix_alerts(tenant_id,student_id,kind,window_day,evidence_json) VALUES(?,?,?,CURRENT_DATE(),?)',[$u['tenant_id'],$s['id'],$kind,json_encode($evidence,JSON_THROW_ON_ERROR)])->rowCount();return $count;}
function si_context(array $u,string $question):array{
 $q=mb_strtolower($question);if(preg_match('/password|secret|api.?key|system prompt|\b(drop|delete|truncate|alter|insert|update)\b|sql|ignore.*instruction|other school/iu',$q))throw new RuntimeException('That question is outside the approved school-data tools.');
 if(in_array($u['role'],['parent','student'],true)){$rows=[];foreach(op_children($u) as $s){$balance=(int)g('SELECT COALESCE(SUM(GREATEST(0,amount_kobo-discount_kobo+penalty_kobo-paid_kobo)),0) FROM fn_invoices WHERE tenant_id=? AND student_id=?',[$u['tenant_id'],$s['id']]);$n=(int)g('SELECT COUNT(*) FROM attendance WHERE tenant_id=? AND student_id=? AND attendance_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 30 DAY)',[$u['tenant_id'],$s['id']]);$present=(int)g("SELECT COUNT(*) FROM attendance WHERE tenant_id=? AND student_id=? AND attendance_date>=DATE_SUB(CURRENT_DATE(),INTERVAL 30 DAY) AND status IN ('present','late')",[$u['tenant_id'],$s['id']]);$rows[]=['linked_student_id'=>(int)$s['id'],'current_balance_kobo'=>$balance,'recorded_days'=>$n,'present_or_late'=>$present];}return ['dataset'=>'my_linked_children','rows'=>$rows,'external_allowed'=>false];}
 if($u['role']==='teacher'&&!ix_can($u,'reports_view')){return ['dataset'=>'my_teaching','rows'=>q('SELECT c.name class,s.name subject FROM ac_allocations a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id AND c.session_name=a.session_name JOIN subjects s ON s.id=a.subject_id AND s.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.teacher_id=?',[$u['tenant_id'],$u['id']])->fetchAll(),'external_allowed'=>false];}
 $key=match(true){(bool)preg_match('/fee|debt|balance|cash|finance/',$q)=>'finance',(bool)preg_match('/payroll|salary|human resources|\bhr\b/',$q)=>'hr',(bool)preg_match('/attendance|absen/',$q)=>'attendance',(bool)preg_match('/admission|conversion/',$q)=>'admissions',(bool)preg_match('/academic|grade|result/',$q)=>'academics',(bool)preg_match('/workload|teacher/',$q)=>'workload',(bool)preg_match('/retention|year.on.year/',$q)=>'retention',(bool)preg_match('/transport|hostel|boarding/',$q)=>'operations',default=>'enrolment'};return ['dataset'=>$key,'rows'=>rp_report($u,$key,['from'=>date('Y-01-01'),'to'=>date('Y-m-d')]),'external_allowed'=>true];
}
function si_copilot(array $u,string $question,?callable $api=null):array{if(mb_strlen($question)<5||mb_strlen($question)>1200)throw new RuntimeException('Ask a school-data question of 5–1200 characters.');$context=si_context($u,$question);$result=['dataset'=>$context['dataset'],'facts'=>$context['rows'],'draft'=>'These are authorized recorded facts. Check date ranges, completeness and report definitions before making a decision.'];if(ix_setting((int)$u['tenant_id'],'copilot_enabled')&&$context['external_allowed']){$key=sv_secrets((int)$u['tenant_id'])['copilot_api_key']??'';if($key==='')throw new RuntimeException('Configure this school’s reviewed AI provider key first.');sv_tx(function()use($u){q('SELECT id FROM users WHERE tenant_id=? AND id=? FOR UPDATE',[$u['tenant_id'],$u['id']]);q('INSERT IGNORE INTO ix_ai_usage VALUES(?,?,CURRENT_DATE(),0)',[$u['tenant_id'],$u['id']]);$used=(int)g('SELECT used FROM ix_ai_usage WHERE tenant_id=? AND user_id=? AND usage_day=CURRENT_DATE() FOR UPDATE',[$u['tenant_id'],$u['id']]);if($used>=5)throw new RuntimeException('Daily Copilot summary limit reached.');q('UPDATE ix_ai_usage SET used=used+1 WHERE tenant_id=? AND user_id=? AND usage_day=CURRENT_DATE()',[$u['tenant_id'],$u['id']]);});$transport=$api??'lp_ai_api';$safe=[];foreach($context['rows'] as $r){$numbers=[];foreach($r as $k=>$v)if(is_numeric($v))$numbers[$k]=$v;$safe[]=$numbers;}$response=$transport('chat/completions',['model'=>'gpt-4.1-mini','messages'=>[['role'=>'system','content'=>'Summarize these numeric school aggregates cautiously as a draft. No names, recommendations about individual children, actions, SQL, external links or claims of causation. State data limitations.'],['role'=>'user','content'=>json_encode(['dataset'=>$context['dataset'],'numeric_rows'=>$safe],JSON_THROW_ON_ERROR)]],'max_completion_tokens'=>500],$key);$draft=trim((string)($response['choices'][0]['message']['content']??''));if($draft===''||mb_strlen($draft)>5000)throw new RuntimeException('Provider returned an invalid draft.');$result['draft']=$draft;}audit('copilot.read','dataset',$context['dataset'].' '.hash('sha256',$question));return $result;}
function si_pickup_actor(array $u,int $sid):void{if(ix_can($u,'pickup_officer'))return;$tid=(int)$u['tenant_id'];if(op_can($u,'driver')&&g("SELECT p.id FROM tm_passengers p JOIN tm_trips t ON t.id=p.trip_id AND t.tenant_id=p.tenant_id WHERE p.tenant_id=? AND p.student_id=? AND p.status='pending' AND t.status='in_progress' AND t.direction='dropoff' AND t.driver_user_id=? AND t.service_day=CURRENT_DATE()",[$tid,$sid,$u['id']]))return;if(op_can($u,'warden')){$r=bd_resident($u,$sid);bd_hostel($u,(int)$r['hostel_id']);return;}throw new RuntimeException('Pickup is not within this account’s assigned duty.');}
function si_pickup_gate(array $u,int $authorization,int $sid,bool $force=false):void{if(!op_has('ix_pickup_tokens')||(!$force&&!ix_setting((int)$u['tenant_id'],'pickup_required')))return;$token=op_text('pickup_token',32,true);if(!preg_match('/^[a-f0-9]{32}$/D',$token))throw new RuntimeException('Enter a valid short-lived pickup token.');$r=q('SELECT * FROM ix_pickup_tokens WHERE tenant_id=? AND token_hash=? FOR UPDATE',[$u['tenant_id'],hash('sha256',$token)])->fetch();if(!$r||$r['status']!=='active'||$r['expires_at']<=date('Y-m-d H:i:s')||(int)$r['authorization_id']!==$authorization||(int)$r['student_id']!==$sid)throw new RuntimeException('Pickup token expired, revoked, used or mismatched.');$issuer=ix_fresh((int)$u['tenant_id'],(int)$r['issued_by']);if($issuer['role']!=='parent')throw new RuntimeException('Active linked guardian required.');op_child($issuer,$sid);q("UPDATE ix_pickup_tokens SET status='used',verified_by=?,identity_note=?,verified_at=NOW() WHERE tenant_id=? AND id=?",[$u['id'],op_text('identity_note',500,true),$u['tenant_id'],$r['id']]);}
function si_wa_response(array $parent,string $command):string{$tid=(int)$parent['tenant_id'];$lines=[];foreach(op_children($parent) as $s){if($command==='attendance'){$r=q('SELECT status FROM attendance WHERE tenant_id=? AND student_id=? AND attendance_date=CURRENT_DATE()',[$tid,$s['id']])->fetch();$lines[]=$s['name'].': '.($r['status']??'No attendance recorded today');}else{$due=(int)g('SELECT COALESCE(SUM(GREATEST(0,amount_kobo-discount_kobo+penalty_kobo-paid_kobo)),0) FROM fn_invoices WHERE tenant_id=? AND student_id=?',[$tid,$s['id']]);$lines[]=$s['name'].': '.op_fmt($due);}}$body=implode("\n",$lines);if($command==='payments')$body.="\nSign in to review invoices and create verified Paystack checkout: ".wc_origin().'/index.php?s=family&view=fees';if($command==='help')return 'Approved commands: BALANCE, ATTENDANCE, PAYMENTS, HELP. STOP revokes WhatsApp consent. Sign in to SchoolOS for records and verified payments.';return $body?:'No linked student records. Contact your school.';}
function si_wa_receive(int $tid,array $json):int{if(!ix_ready())return 0;$cfg=eg_config($tid);$count=0;foreach($json['entry']??[] as $entry)foreach($entry['changes']??[] as $change){$v=$change['value']??[];if((string)($v['metadata']['phone_number_id']??'')!==(string)($cfg['whatsapp_phone_id']??''))continue;foreach($v['messages']??[] as $message){$id=(string)($message['id']??'');$text=strtoupper(trim((string)($message['text']['body']??'')));$phone=cmPhone((string)($message['from']??''));if($id===''||strlen($id)>190)continue;$command=['BALANCE'=>'balance','ATTENDANCE'=>'attendance','PAYMENTS'=>'payments','HELP'=>'help','STOP'=>'stop'][$text]??'unknown';$parents=q("SELECT u.* FROM users u JOIN eg_contacts c ON c.user_id=u.id AND c.tenant_id=u.tenant_id WHERE u.tenant_id=? AND u.active=1 AND u.role='parent' AND c.channel='whatsapp' AND c.verified=1 AND c.address=?",[$tid,$phone])->fetchAll();$parent=count($parents)===1?$parents[0]:null;
 $count+=sv_tx(function()use($tid,$id,$command,$parent){if(q("INSERT IGNORE INTO ix_wa_inbound(tenant_id,provider_id,command,outcome,user_id) VALUES(?,?,?,'received',?)",[$tid,$id,$command,$parent['id']??null])->rowCount()!==1)return 0;$in=(int)$GLOBALS['pdo']->lastInsertId();$outcome='not_authorized';if($parent&&$command==='stop'){q("UPDATE eg_consents SET status='revoked',recorded_by=?,evidence='Explicit signed WhatsApp STOP command' WHERE tenant_id=? AND user_id=? AND channel='whatsapp'",[$parent['id'],$tid,$parent['id']]);$outcome='opted_out';}elseif($parent&&$command!=='unknown'&&eg_consent($tid,(int)$parent['id'],'whatsapp','operational')){$flow=q("SELECT f.*,u.role,u.active FROM ix_wa_flows f JOIN users u ON u.id=f.approved_by AND u.tenant_id=f.tenant_id WHERE f.tenant_id=? AND f.command=? AND f.status='approved'",[$tid,$command])->fetch();if($flow&&$flow['active']&&ix_can(ix_fresh($tid,(int)$flow['approved_by']),'flow_approver')){sv_need(ix_fresh($tid,(int)$flow['created_by']),'communications_manager');$body=si_wa_response($parent,$command);q("INSERT INTO eg_campaigns(tenant_id,title,body,kind,audience,recipient_id,purpose,channels_json,template_id,source_key,send_at,status,created_by) VALUES(?,? ,?,'announcement','recipient',?,'operational','[\"whatsapp\"]',?,?,NOW(),'scheduled',?)",[$tid,'School account update',$body,$parent['id'],$flow['template_id'],'WA-IN-'.$in,$flow['created_by']]);$outcome='queued';}}q('UPDATE ix_wa_inbound SET outcome=? WHERE tenant_id=? AND id=?',[$outcome,$tid,$in]);return 1;});}}
 return $count;}
function si_action(array $u,string $a):string{
 $tid=(int)$u['tenant_id'];$uid=(int)$u['id'];
 if($a==='copilot'){$_SESSION['ix_copilot']=si_copilot($u,op_text('question',1200,true));return 'Authorized facts and reviewable draft prepared. No action was executed.';}
 if($a==='scan')return si_scan($u).' new explainable alerts awaiting human review.';
 if($a==='review_alert'){ix_need($u,'success_reviewer');$r=ix_own('ix_alerts',$u,op_id('alert_id'));q('UPDATE ix_alerts SET status=?,review_note=?,reviewed_by=? WHERE tenant_id=? AND id=?',[sv_enum('status',['reviewed','dismissed']),op_text('review_note',3000,true),$uid,$tid,$r['id']]);audit('success.alert.review','alert',(string)$r['id']);return 'Human review recorded. No automatic label, sanction or parent message was applied.';}
 if($a==='draft'){$kind=sv_enum('kind',['message','report']);$payload=[];if($kind==='report'){$key=sv_enum('dataset',array_keys(rp_columns()));rp_require($u,$key);$payload=['dataset'=>$key,'filters'=>rp_filters($_POST)];}else{sv_need($u,'communications_manager');$recipient=sv_own('users',$u,op_id('recipient_id'));$payload=['recipient_id'=>(int)$recipient['id'],'title'=>op_text('title',200,true),'body'=>op_text('body',5000,true)];}q('INSERT INTO ix_drafts(tenant_id,user_id,kind,payload_json) VALUES(?,?,?,?)',[$tid,$uid,$kind,json_encode($payload,JSON_THROW_ON_ERROR)]);return 'Immutable draft submitted for a different reviewer. The Copilot never executes database commands from natural language.';}
 if($a==='review_draft'||$a==='execute_draft'){return sv_tx(function()use($u,$tid,$uid,$a){$d=ix_own('ix_drafts',$u,op_id('draft_id'),true);$p=json_decode($d['payload_json'],true);$author=ix_fresh($tid,(int)$d['user_id']);if($d['kind']==='message'){sv_need($u,'communications_manager');sv_need($author,'communications_manager');sv_own('users',$u,(int)$p['recipient_id']);}else{rp_require($u,$p['dataset']);rp_require($author,$p['dataset']);}if($a==='review_draft'){if($d['status']!=='pending'||(int)$d['user_id']===$uid)throw new RuntimeException('A different reviewer must approve a pending draft.');q('UPDATE ix_drafts SET status=?,reviewed_by=?,review_note=? WHERE tenant_id=? AND id=?',[sv_enum('status',['approved','rejected']),$uid,op_text('review_note',1000,true),$tid,$d['id']]);return 'Draft review recorded.';}if($d['status']!=='approved')throw new RuntimeException('Only an approved unexecuted draft can run.');$reviewer=ix_fresh($tid,(int)$d['reviewed_by']);if($d['kind']==='message'){sv_need($reviewer,'communications_manager');q("INSERT INTO eg_campaigns(tenant_id,title,body,kind,audience,recipient_id,purpose,channels_json,source_key,send_at,status,created_by) VALUES(?,?,?,'announcement','recipient',?,'operational','[\"inapp\"]',?,NOW(),'scheduled',?)",[$tid,$p['title'],$p['body'],$p['recipient_id'],'COPILOT-'.$d['id'],$uid]);$result=(int)$GLOBALS['pdo']->lastInsertId();}else{rp_require($reviewer,$p['dataset']);$def=['name'=>'Approved report draft #'.$d['id'],'dataset'=>$p['dataset'],'filters_json'=>json_encode($p['filters']),'columns_json'=>json_encode(rp_columns()[$p['dataset']])];$result=rp_export($u,$def,'DRAFT-'.$d['id']);}q("UPDATE ix_drafts SET status='executed',result_id=? WHERE tenant_id=? AND id=?",[$result,$tid,$d['id']]);return 'Approved payload executed once with current permissions.';});}
 if($a==='pickup_issue'){if($u['role']!=='parent')throw new RuntimeException('Linked parent required.');return sv_tx(function()use($u,$tid,$uid){$r=q("SELECT * FROM pp_requests WHERE tenant_id=? AND id=? AND user_id=? AND kind='pickup' FOR UPDATE",[$tid,op_id('authorization_id'),$uid])->fetch();if(!$r||$r['status']!=='approved'||$r['starts_on']!==date('Y-m-d'))throw new RuntimeException('Use a current approved pickup authorization.');op_child($u,(int)$r['student_id']);$minutes=sv_qty('minutes',30);if($minutes<5)throw new RuntimeException('Use 5–30 minutes.');q("UPDATE ix_pickup_tokens SET status='revoked' WHERE tenant_id=? AND authorization_id=? AND status='active'",[$tid,$r['id']]);$token=bin2hex(random_bytes(16));q('INSERT INTO ix_pickup_tokens(tenant_id,authorization_id,student_id,token_hash,expires_at,issued_by) VALUES(?,?,?,?,?,?)',[$tid,$r['id'],$r['student_id'],hash('sha256',$token),min(date('Y-m-d H:i:s',time()+$minutes*60),date('Y-m-d').' 23:59:59'),$uid]);$_SESSION['ix_pickup_once']=$token;return 'Short-lived one-time pickup credential issued. Staff still physically verify guardian identity.';});}
 if($a==='pickup_revoke'){if($u['role']!=='parent')throw new RuntimeException('Parent required.');$r=ix_own('ix_pickup_tokens',$u,op_id('token_id'));if((int)$r['issued_by']!==$uid)throw new RuntimeException('Token unavailable.');q("UPDATE ix_pickup_tokens SET status='revoked' WHERE tenant_id=? AND id=? AND status='active'",[$tid,$r['id']]);return 'Token revoked.';}
 if($a==='handover'){return sv_tx(function()use($u,$tid,$uid){$token=op_text('pickup_token',32,true);$t=q('SELECT * FROM ix_pickup_tokens WHERE tenant_id=? AND token_hash=?',[$tid,hash('sha256',$token)])->fetch();if(!$t)throw new RuntimeException('Pickup unavailable.');si_pickup_actor($u,(int)$t['student_id']);$r=q('SELECT * FROM pp_requests WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$t['authorization_id']])->fetch();if(!$r||$r['status']!=='approved'||$r['kind']!=='pickup'||$r['starts_on']!==date('Y-m-d')||op_text('identity_checked',10)!=='yes'||mb_strlen(op_text('identity_note',500))<8)throw new RuntimeException('Current approval and physical guardian identity check required.');si_pickup_gate($u,(int)$r['id'],(int)$r['student_id'],true);q("UPDATE pp_requests SET status='collected',reviewed_by=? WHERE tenant_id=? AND id=?",[$uid,$tid,$r['id']]);$trips=q("SELECT p.trip_id,t.driver_user_id FROM tm_passengers p JOIN tm_trips t ON t.id=p.trip_id AND t.tenant_id=p.tenant_id WHERE p.tenant_id=? AND p.student_id=? AND p.status='pending' AND t.direction='dropoff' AND t.status='in_progress' AND t.service_day=CURRENT_DATE()",[$tid,$r['student_id']])->fetchAll();if(count($trips)>1)throw new RuntimeException('Multiple live drop-off trips require manifest-specific handover.');if($trips){$trip=$trips[0];if(!ix_can($u,'pickup_officer')&&(int)$trip['driver_user_id']!==$uid)throw new RuntimeException('Use the assigned driver manifest for this handover.');q("UPDATE tm_passengers SET status='handed_over',authorization_id=?,identity_note=?,updated_at=NOW() WHERE tenant_id=? AND trip_id=? AND student_id=?",[$r['id'],op_text('identity_note',500),$tid,$trip['trip_id'],$r['student_id']]);};op_notify($u,(int)$r['student_id'],'transport','Guardian handover recorded after identity and one-time-token verification.','SMART-PICKUP-'.$t['id']);audit('pickup.verified','student',(string)$r['student_id']);return 'Guardian handover verified and recorded once. Boarding leave permits remain separate requirements.';});}
 if($a==='flow'){sv_need($u,'communications_manager');$command=sv_enum('command',['balance','attendance','payments','help']);$tpl=sv_own('eg_templates',$u,op_id('template_id'));if($tpl['wa_template']==='')throw new RuntimeException('Use a Meta-approved WhatsApp template.');q('INSERT INTO ix_wa_flows(tenant_id,command,template_id,created_by,review_note) VALUES(?,?,?,?,?)',[$tid,$command,$tpl['id'],$uid,op_text('review_note',500,true)]);return 'Deterministic flow saved as draft. A different authorized flow approver must approve it.';}
 if($a==='approve_flow'){ix_need($u,'flow_approver');$f=ix_own('ix_wa_flows',$u,op_id('flow_id'));if($f['status']!=='draft'||(int)$f['created_by']===$uid)throw new RuntimeException('A different reviewer must approve the flow.');q("UPDATE ix_wa_flows SET status='approved',approved_by=? WHERE tenant_id=? AND id=? AND status='draft'",[$uid,$tid,$f['id']]);return 'Approved conversational flow enabled. Only signed, verified, consented parent commands can use it.';}
 throw new RuntimeException('Unsupported innovation action.');
}
function si_render(array $u):void{
 $tid=(int)$u['tenant_id'];$view=ix_tabs('innovations',['copilot'=>'School Copilot','drafts'=>'Approved drafts','success'=>'Student success alerts','pickup'=>'Smart pickup','whatsapp'=>'WhatsApp-first flows'],'copilot');op_card(ucfirst($view));
 if($view==='copilot'){ix_form('si_copilot',['question'=>['Ask about authorized enrolment, attendance, results, workload or balances','textarea']],'Ask School Copilot');if(isset($_SESSION['ix_copilot'])){$r=$_SESSION['ix_copilot'];echo '<h4>'.e($r['dataset']).'</h4><pre>'.e(json_encode($r['facts'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre><p>'.nl2br(e($r['draft'])).'</p>';unset($_SESSION['ix_copilot']);}echo '<p>Queries select fixed permission-checked tools, never generated SQL. Families get linked-child facts; teachers get assigned teaching facts. Optional provider summaries receive numeric school aggregates only, not your raw question, names or child records. Outputs are drafts; sensitive actions require separate approval.</p>';}
 elseif($view==='drafts'){
  $manager=sv_can($u,'communications_manager')||ix_can($u,'reports_view');if(!$manager)throw new RuntimeException('Reporting or communications access required.');ix_form('si_draft',['kind'=>['Draft type',['report'=>'Aggregate report','message'=>'In-app message']],'dataset'=>['Report dataset',array_combine(array_keys(rp_columns()),array_keys(rp_columns()))],'from'=>['Report from','date',date('Y-01-01')],'to'=>['Report to','date',date('Y-m-d')],'class_id'=>['Class ID (0 for school)','number','0'],'recipient_id'=>['Message recipient ID','number','0'],'title'=>['Message title','text','',false],'body'=>['Message body','textarea','',false]],'Submit immutable draft');$rows=q('SELECT id,user_id,kind,payload_json,status,reviewed_by,review_note,result_id FROM ix_drafts WHERE tenant_id=? ORDER BY id DESC LIMIT 100',[$tid])->fetchAll();$visible=[];foreach($rows as $r){$p=json_decode($r['payload_json'],true);try{if($r['kind']==='report')rp_require($u,$p['dataset']);else sv_need($u,'communications_manager');$visible[]=$r;}catch(Throwable $e){}}op_table($visible,['ID','Author','Type','Approved payload','Status','Reviewer','Review','Result ID']);ix_form('si_review_draft',['draft_id'=>['Pending draft ID','number'],'status'=>['Decision',['approved'=>'Approve independently','rejected'=>'Reject']],'review_note'=>['Review record','textarea']],'Review draft');ix_form('si_execute_draft',['draft_id'=>['Approved draft ID','number']],'Execute exact approved payload once');
 }elseif($view==='success'){ix_need($u,'success_reviewer');ix_form('si_scan',[],'Evaluate recorded evidence');$rows=q('SELECT a.id,s.name,a.kind,a.window_day,a.evidence_json,a.status,a.review_note FROM ix_alerts a JOIN students s ON s.id=a.student_id AND s.tenant_id=a.tenant_id WHERE a.tenant_id=? ORDER BY a.id DESC LIMIT 200',[$tid])->fetchAll();op_table($rows,['ID','Student','Indicator','Window','Evidence / rule','Review status','Follow-up']);ix_form('si_review_alert',['alert_id'=>['Alert ID','number'],'status'=>['Decision',['reviewed'=>'Reviewed / support plan','dismissed'=>'Dismissed with reason']],'review_note'=>['Human interpretation, exceptions and support follow-up','textarea']],'Record human review');echo '<p>Indicators are explainable prompts for support, not diagnoses or automatic decisions. Missing observations, subject changes, enrollment and approved absence must be checked. No automatic sanctions, promotion decisions or external alerts are sent.</p>';}
 elseif($view==='pickup'){if($u['role']==='parent'){foreach(op_children($u) as $s)echo '<p>'.e($s['name']).': create an authorization in <a href="?s=family&amp;child='.(int)$s['id'].'&amp;view=pickup">Family Space</a>, then wait for school approval.</p>';ix_form('si_pickup_issue',['authorization_id'=>['Today’s approved authorization ID','number'],'minutes'=>['Token lifetime minutes (5–30)','number','15']],'Issue / rotate pickup credential');if(isset($_SESSION['ix_pickup_once'])){$token=$_SESSION['ix_pickup_once'];echo '<div style="max-width:200px">'.lib_qr($token).'</div><p>Copy once: <code>'.e($token).'</code></p>';unset($_SESSION['ix_pickup_once']);}op_table(q('SELECT id,authorization_id,student_id,expires_at,status FROM ix_pickup_tokens WHERE tenant_id=? AND issued_by=? ORDER BY id DESC LIMIT 40',[$tid,$u['id']])->fetchAll(),['Token ID','Authorization','Child','Expires','Status']);ix_form('si_pickup_revoke',['token_id'=>['My token ID','number']],'Revoke token');}else{ix_form('si_handover',['pickup_token'=>['Scan / enter guardian’s short-lived credential','text'],'identity_checked'=>['I physically matched guardian identity to the approved authorization','check'],'identity_note'=>['Identity verification evidence / handover note','text']],'Verify and record handover');}echo '<p>Possession of a QR code does not prove identity. School staff verify the approved guardian in person; drivers/wardens are constrained to assigned duty. Expired/revoked/used credentials cannot authorize another collection.</p>';}
 else{if(!sv_can($u,'communications_manager')&&!ix_can($u,'flow_approver'))throw new RuntimeException('Communications or flow-approval access required.');op_table(q('SELECT id,command,template_id,status,created_by,approved_by,review_note FROM ix_wa_flows WHERE tenant_id=?',[$tid])->fetchAll(),['ID','Command','Template','Status','Author','Approver','Review']);if(sv_can($u,'communications_manager'))ix_form('si_flow',['command'=>['Bounded flow',['balance'=>'BALANCE — linked-child balances','attendance'=>'ATTENDANCE — today’s recorded statuses','payments'=>'PAYMENTS — authenticated payment portal','help'=>'HELP — available commands']],'template_id'=>['Meta-approved template',op_choices(q("SELECT id,name FROM eg_templates WHERE tenant_id=? AND wa_template<>''",[$tid])->fetchAll())],'review_note'=>['School review of privacy, wording, consent and Meta template','textarea']],'Create flow draft');if(ix_can($u,'flow_approver'))ix_form('si_approve_flow',['flow_id'=>['Draft flow ID','number']],'Approve as a different reviewer');op_table(q('SELECT command,outcome,created_at FROM ix_wa_inbound WHERE tenant_id=? ORDER BY id DESC LIMIT 100',[$tid])->fetchAll(),['Command','Outcome','Received']);echo '<p>Incoming messages use the existing signed Meta callback, exact phone ID, verified unique parent contact and current operational consent. Replies enter the existing consented/credited provider queue. STOP revokes WhatsApp consent. Payment links require portal login; an incoming message never confirms payment.</p>';}
 echo '</section>';
}
